#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub enum Expr {
    Literal(Literal),
    NameRef(NameRef),
    FieldExpr(FieldExpr),
    CallExpr(CallExpr),
    RecordExpr(RecordExpr),
    ParenExpr(ParenExpr),
    ListExpr(ListExpr),
    OrderedExpr(OrderedExpr),
    BinExpr(BinExpr),
    PrefixExpr(PrefixExpr),
    MatchExpr(MatchExpr),
    AttemptExpr(AttemptExpr),
    RejectExpr(RejectExpr),
    PropagateExpr(PropagateExpr),
    LambdaExpr(LambdaExpr),
    RoutePathExpr(RoutePathExpr),
    GenericExpr(GenericExpr),
    NullableExpr(NullableExpr),
    ElisionExpr(ElisionExpr),
}

impl AstNode for Expr {
    fn can_cast(kind: SyntaxKind) -> bool {
        kind == LITERAL
            || kind == NAME_REF
            || kind == FIELD_EXPR
            || kind == CALL_EXPR
            || kind == RECORD_EXPR
            || kind == PAREN_EXPR
            || kind == LIST_EXPR
            || kind == ORDERED_EXPR
            || kind == BIN_EXPR
            || kind == PREFIX_EXPR
            || kind == MATCH_EXPR
            || kind == ATTEMPT_EXPR
            || kind == REJECT_EXPR
            || kind == PROPAGATE_EXPR
            || kind == LAMBDA_EXPR
            || kind == ROUTE_PATH_EXPR
            || kind == GENERIC_EXPR
            || kind == NULLABLE_EXPR
            || kind == ELISION_EXPR
    }
    fn cast(syntax: SyntaxNode) -> Option<Self> {
        let kind = syntax.kind();
        if kind == LITERAL {
            return Some(Self::Literal(Literal { syntax }));
        }
        if kind == NAME_REF {
            return Some(Self::NameRef(NameRef { syntax }));
        }
        if kind == FIELD_EXPR {
            return Some(Self::FieldExpr(FieldExpr { syntax }));
        }
        if kind == CALL_EXPR {
            return Some(Self::CallExpr(CallExpr { syntax }));
        }
        if kind == RECORD_EXPR {
            return Some(Self::RecordExpr(RecordExpr { syntax }));
        }
        if kind == PAREN_EXPR {
            return Some(Self::ParenExpr(ParenExpr { syntax }));
        }
        if kind == LIST_EXPR {
            return Some(Self::ListExpr(ListExpr { syntax }));
        }
        if kind == ORDERED_EXPR {
            return Some(Self::OrderedExpr(OrderedExpr { syntax }));
        }
        if kind == BIN_EXPR {
            return Some(Self::BinExpr(BinExpr { syntax }));
        }
        if kind == PREFIX_EXPR {
            return Some(Self::PrefixExpr(PrefixExpr { syntax }));
        }
        if kind == MATCH_EXPR {
            return Some(Self::MatchExpr(MatchExpr { syntax }));
        }
        if kind == ATTEMPT_EXPR {
            return Some(Self::AttemptExpr(AttemptExpr { syntax }));
        }
        if kind == REJECT_EXPR {
            return Some(Self::RejectExpr(RejectExpr { syntax }));
        }
        if kind == PROPAGATE_EXPR {
            return Some(Self::PropagateExpr(PropagateExpr { syntax }));
        }
        if kind == LAMBDA_EXPR {
            return Some(Self::LambdaExpr(LambdaExpr { syntax }));
        }
        if kind == ROUTE_PATH_EXPR {
            return Some(Self::RoutePathExpr(RoutePathExpr { syntax }));
        }
        if kind == GENERIC_EXPR {
            return Some(Self::GenericExpr(GenericExpr { syntax }));
        }
        if kind == NULLABLE_EXPR {
            return Some(Self::NullableExpr(NullableExpr { syntax }));
        }
        if kind == ELISION_EXPR {
            return Some(Self::ElisionExpr(ElisionExpr { syntax }));
        }
        None
    }
    fn syntax(&self) -> &SyntaxNode {
        match self {
            Self::Literal(it) => it.syntax(),
            Self::NameRef(it) => it.syntax(),
            Self::FieldExpr(it) => it.syntax(),
            Self::CallExpr(it) => it.syntax(),
            Self::RecordExpr(it) => it.syntax(),
            Self::ParenExpr(it) => it.syntax(),
            Self::ListExpr(it) => it.syntax(),
            Self::OrderedExpr(it) => it.syntax(),
            Self::BinExpr(it) => it.syntax(),
            Self::PrefixExpr(it) => it.syntax(),
            Self::MatchExpr(it) => it.syntax(),
            Self::AttemptExpr(it) => it.syntax(),
            Self::RejectExpr(it) => it.syntax(),
            Self::PropagateExpr(it) => it.syntax(),
            Self::LambdaExpr(it) => it.syntax(),
            Self::RoutePathExpr(it) => it.syntax(),
            Self::GenericExpr(it) => it.syntax(),
            Self::NullableExpr(it) => it.syntax(),
            Self::ElisionExpr(it) => it.syntax(),
        }
    }
}

