#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub enum BlockItem {
    Stmt(Stmt),
    Member(Member),
    Elision(Elision),
}

impl AstNode for BlockItem {
    fn can_cast(kind: SyntaxKind) -> bool {
        Stmt::can_cast(kind) || kind == MEMBER || kind == ELISION
    }
    fn cast(syntax: SyntaxNode) -> Option<Self> {
        let kind = syntax.kind();
        if Stmt::can_cast(kind) {
            return Stmt::cast(syntax).map(Self::Stmt);
        }
        if kind == MEMBER {
            return Some(Self::Member(Member { syntax }));
        }
        if kind == ELISION {
            return Some(Self::Elision(Elision { syntax }));
        }
        None
    }
    fn syntax(&self) -> &SyntaxNode {
        match self {
            Self::Stmt(it) => it.syntax(),
            Self::Member(it) => it.syntax(),
            Self::Elision(it) => it.syntax(),
        }
    }
}

impl From<Stmt> for BlockItem {
    fn from(node: Stmt) -> BlockItem {
        BlockItem::Stmt(node)
    }
}

impl From<Member> for BlockItem {
    fn from(node: Member) -> BlockItem {
        BlockItem::Member(node)
    }
}

impl From<Elision> for BlockItem {
    fn from(node: Elision) -> BlockItem {
        BlockItem::Elision(node)
    }
}

