#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub enum Pat {
    CasePat(CasePat),
    LiteralPat(LiteralPat),
    WildcardPat(WildcardPat),
}

impl AstNode for Pat {
    fn can_cast(kind: SyntaxKind) -> bool {
        kind == CASE_PAT || kind == LITERAL_PAT || kind == WILDCARD_PAT
    }
    fn cast(syntax: SyntaxNode) -> Option<Self> {
        let kind = syntax.kind();
        if kind == CASE_PAT {
            return Some(Self::CasePat(CasePat { syntax }));
        }
        if kind == LITERAL_PAT {
            return Some(Self::LiteralPat(LiteralPat { syntax }));
        }
        if kind == WILDCARD_PAT {
            return Some(Self::WildcardPat(WildcardPat { syntax }));
        }
        None
    }
    fn syntax(&self) -> &SyntaxNode {
        match self {
            Self::CasePat(it) => it.syntax(),
            Self::LiteralPat(it) => it.syntax(),
            Self::WildcardPat(it) => it.syntax(),
        }
    }
}

impl From<CasePat> for Pat {
    fn from(node: CasePat) -> Pat {
        Pat::CasePat(node)
    }
}

impl From<LiteralPat> for Pat {
    fn from(node: LiteralPat) -> Pat {
        Pat::LiteralPat(node)
    }
}

impl From<WildcardPat> for Pat {
    fn from(node: WildcardPat) -> Pat {
        Pat::WildcardPat(node)
    }
}

